        if(너비값->անվանակարգ_արժեք==4){միջոցառում(տնօրինող_առարկա,순번+1);return 1;}if(너비값->անվանակարգ_արժեք==5){Կարեւոր_գործարքներ[տնօրինող_առարկա]=순번+1;տախտակ_Տերմինալ(3);return 1;}
        if(너비값->անվանակարգ_արժեք==1)return 1;
